def to_nine(g):
    """원본과 동일: 입력 이하의 가장 가까운 기준값(오차 허용 1e-9)."""
    if not math.isfinite(g) or not 1 <= g <= 5:
        raise ValueError('5등급제 평균은 1~5 사이여야 합니다.')
    lo, hi, best = 0, len(CONV) - 1, 0
    while lo <= hi:
        mid = (lo + hi) // 2
        if CONV[mid][0] <= g + 1e-9:
            best = mid
            lo = mid + 1
        else:
            hi = mid - 1
    return CONV[best][1]


def required_average(grades, remaining, target):
    """남은 성적 합계를 0.01 단위로 탐색해 계단형 환산표를 정확히 역산."""
    earned = sum(round(g * 100) for g in grades)
    lo, hi = remaining * 100, remaining * 500
    best = lo
    while lo <= hi:
        mid = (lo + hi) // 2
        if to_nine((earned + mid) / 500) <= target + 1e-9:
            best = mid
            lo = mid + 1
        else:
            hi = mid - 1
    return best / (100 * remaining)


def make_plan(required_mean, count, mode):
    """평균을 유지하며 경계에서 자동으로 기울기를 줄인다.
    출력값은 0.01 단위로 내림하여 반올림 탓에 목표를 놓치지 않는다.
    낮은 등급 숫자가 더 우수한 성적이다.
    """
    if count < 1:
        return []
    if count == 1 or mode == 'steady':
        raw = [required_mean] * count
    else:
        # 학기당 기본 0.30등급 변화. 1~5 범위에 맞추어 축소.
        half_width = min(0.30 * (count - 1) / 2,
                         required_mean - 1., 5. - required_mean)
        offsets = [-half_width + 2 * half_width * i / (count - 1)
                   for i in range(count)]
        sign = -1 if mode == 'growth' else 1
        raw = [required_mean + sign * d for d in offsets]
    return [max(1., min(5., math.floor((x + 1e-9) * 100) / 100)) for x in raw]


